package vn.iotstar.controller;
import vn.iotstar.dto.ApiResponse; import vn.iotstar.exception.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.multipart.*;
@RestControllerAdvice public class ApiExceptionHandler { private ResponseEntity<ApiResponse<Void>> e(HttpStatus s,String m){return ResponseEntity.status(s).body(new ApiResponse<>(false,m,null));}
 @ExceptionHandler(NotFoundException.class) ResponseEntity<ApiResponse<Void>> notFound(NotFoundException x){return e(HttpStatus.NOT_FOUND,x.getMessage());} @ExceptionHandler(ConflictException.class) ResponseEntity<ApiResponse<Void>> conflict(ConflictException x){return e(HttpStatus.CONFLICT,x.getMessage());}
 @ExceptionHandler({IllegalArgumentException.class,StorageException.class,MultipartException.class,MethodArgumentNotValidException.class}) ResponseEntity<ApiResponse<Void>> bad(Exception x){return e(HttpStatus.BAD_REQUEST,x.getMessage()==null?"Dữ liệu không hợp lệ":x.getMessage());} @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> unknown(Exception x){return e(HttpStatus.INTERNAL_SERVER_ERROR,"Đã xảy ra lỗi hệ thống");}}
